-- Pense Run: expansão aditiva com percursos privados e revisão otimista.
create table public.pensefit_run_profiles (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,date date not null default current_date,data jsonb not null check(jsonb_typeof(data)='object' and octet_length(data::text)<=8388608),revision bigint not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,id));
create index pensefit_run_profiles_owner_date on public.pensefit_run_profiles(user_id,date desc);
alter table public.pensefit_run_profiles enable row level security;
revoke all on public.pensefit_run_profiles from public,anon,authenticated;
grant select,insert,update,delete on public.pensefit_run_profiles to authenticated;
create policy pensefit_run_profiles_owner on public.pensefit_run_profiles for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create trigger pensefit_run_profiles_stamp before update on public.pensefit_run_profiles for each row execute function public.pensefit_stamp_record();
